use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn split_crate (crate_path : & Path) -> Result < () > { let rust_files = find_rust_files (crate_path) ; if rust_files . is_empty () { return Ok (()) ; } let crate_name = if crate_path . to_string_lossy () . ends_with ("..") { "split-decls-rs" } else { crate_path . file_name () . and_then (| n | n . to_str ()) . unwrap_or ("unknown") } ; println ! ("🔄 Processing {}: {} files" , crate_name , rust_files . len ()) ; let output_dir = Path :: new ("../output2") . join (format ! ("wrapped-{}/src/decls" , crate_name)) ; fs :: create_dir_all (& output_dir) ? ; let mut total_count = 0 ; for rust_file in rust_files { if let Ok (content) = fs :: read_to_string (& rust_file) { if let Ok (parsed) = syn :: parse_file (& content) { let module_name = if rust_file . to_string_lossy () . contains ("/bin/") { rust_file . file_stem () . and_then (| s | s . to_str ()) . unwrap_or ("unknown") } else { rust_file . file_stem () . and_then (| s | s . to_str ()) . unwrap_or ("lib") } ; for (i , item) in parsed . items . iter () . enumerate () { let (decl_type , name) = match item { Item :: Fn (f) => ("fn" , f . sig . ident . to_string ()) , Item :: Struct (s) => ("struct" , s . ident . to_string ()) , Item :: Enum (e) => ("enum" , e . ident . to_string ()) , Item :: Trait (t) => ("trait" , t . ident . to_string ()) , Item :: Impl (_) => ("impl" , format ! ("impl_{}" , i)) , Item :: Const (c) => ("const" , c . ident . to_string ()) , Item :: Static (s) => ("static" , s . ident . to_string ()) , Item :: Type (t) => ("type" , t . ident . to_string ()) , Item :: Union (u) => ("union" , u . ident . to_string ()) , _ => continue , } ; let wrapped = format ! ("use serde::{{Deserialize, Serialize}};\nuse std::collections::HashMap;\n\n{}" , item . to_token_stream ()) ; let decl_size = wrapped . len () ; let complexity = match decl_size { 0 ..= 200 => 1 , 201 ..= 400 => 2 , 401 ..= 600 => 3 , 601 ..= 800 => 4 , 801 ..= 1000 => 5 , 1001 ..= 1300 => 6 , 1301 ..= 1700 => 7 , 1701 ..= 2500 => 8 , 2501 ..= 4000 => 9 , _ => 10 , } ; let module_dir = output_dir . join (module_name) . join (decl_type) . join (complexity . to_string ()) ; fs :: create_dir_all (& module_dir) ? ; let file_path = module_dir . join (format ! ("{}.rs" , name)) ; fs :: write (file_path , wrapped) ? ; total_count += 1 ; } } } } if total_count > 0 { let wrapped_lib_dir = Path :: new ("../output2") . join (format ! ("wrapped-{}/src" , crate_name)) ; fs :: create_dir_all (& wrapped_lib_dir) ? ; let new_lib = "pub mod decls;\npub use decls::*;\n" ; fs :: write (wrapped_lib_dir . join ("lib.rs") , new_lib) ? ; println ! ("✅ Split {} items from {}" , total_count , crate_name) ; } Ok (()) }